import streamlit as st
import streamlit.components.v1 as components
from Conversation.conversation import ConversationalAgent


def load_tab_css():
    with open("static/tab.css", "r") as f:
        css = f"<style>{f.read()}</style>"
        st.markdown(css, unsafe_allow_html=True)


def initialize_session_state():
    if "history" not in st.session_state:
        st.session_state.history = []
    if "search_keywords" not in st.session_state:
        st.session_state.search_keywords = []
    if "doc_sources" not in st.session_state:
        st.session_state.doc_sources = []
    if "google_sources" not in st.session_state:
        st.session_state.google_sources = []
    if "token_count" not in st.session_state:
        st.session_state.token_count = 0
    if "chat_placeholder" not in st.session_state:
        st.session_state.chat_placeholder = None
    if "agent" not in st.session_state:
        st.session_state.agent = ConversationalAgent()


def enterKeypress_submit_button_html():
    return components.html("""
                            <script>
                                const streamlitDoc = window.parent.document;
                                const buttons = Array.from(
                                    streamlitDoc.querySelectorAll('.stButton > button')
                                );
                                const submitButton = buttons.find(
                                    el => el.innerText === 'Submit'
                                );
                                streamlitDoc.addEventListener('keydown', function(e) {
                                    switch (e.key) {
                                        case 'Enter':
                                            submitButton.click();
                                            break;
                                    }
                                });
                            </script>
                            """,
                           height=0,
                           width=0,
                           )

import streamlit as st

import re

import pypdf

from langchain.text_splitter import RecursiveCharacterTextSplitter
from langchain.docstore.document import Document
from langchain.vectorstores import FAISS
from langchain.embeddings import OpenAIEmbeddings

from openai.error import AuthenticationError


class PDFDBStore:
    """

    """

    def __init__(self, pdf_file):

        self.reader = pypdf.PdfReader(pdf_file)
        self.embeddings = OpenAIEmbeddings(openai_api_key=st.session_state['openai_api_key'])
        self.vector_store = None

    def is_valid_key(self):

        try:
            embeddings = OpenAIEmbeddings(openai_api_key=st.session_state['openai_api_key'])
            embeddings.embed_query("test")

        except AuthenticationError as e:
            return False

        return True

    def extract_metadata_from_pdf(self):
        metadata = self.reader.metadata
        return {
            "title": metadata.get("/Title", "").strip(),
            "author": metadata.get("/Author", "").strip(),
            "creation_date": metadata.get("/CreationDate", "").strip(),
        }

    def extract_pages_from_pdf(self):
        """
        Extracts the text from each page of the PDF.
        :return: A list of tuples containing the page number and the extracted text.
        """

        pages = []
        for page_num, page in enumerate(self.reader.pages):
            text = page.extract_text()
            if text.strip():  # Check if extracted text is not empty
                pages.append((page_num + 1, text))

        return pages

    def parse_pdf(self):
        """
        Extracts the title and text from each page of the PDF.
        :return: A tuple containing the title and a list of tuples with page numbers and extracted text.
        """

        metadata = self.extract_metadata_from_pdf()
        pages = self.extract_pages_from_pdf()

        return pages, metadata

    @staticmethod
    def merge_hyphenated_words(text):
        return re.sub(r"(\w)-\n(\w)", r"\1\2", text)

    @staticmethod
    def fix_newlines(text):
        return re.sub(r"(?<!\n)\n(?!\n)", " ", text)

    @staticmethod
    def remove_multiple_newlines(text):
        return re.sub(r"\n{2,}", "\n", text)

    @staticmethod
    def clean_text(pages, cleaning_functions):
        cleaned_pages = []
        for page_num, text in pages:
            for cleaning_function in cleaning_functions:
                text = cleaning_function(text)
            cleaned_pages.append((page_num, text))

        return cleaned_pages

    @staticmethod
    def text_to_docs(text, metadata):
        """Converts list of strings to a list of Documents with metadata."""
        doc_chunks = []

        for page_num, page in text:
            text_splitter = RecursiveCharacterTextSplitter(
                chunk_size=1000,
                separators=["\n\n", "\n", ".", "!", "?", ",", " ", ""],
                chunk_overlap=200,
            )
            chunks = text_splitter.split_text(page)
            for i, chunk in enumerate(chunks):
                doc = Document(
                    page_content=chunk,
                    metadata={
                        "page_number": page_num,
                        "chunk": i,
                        "source": f"p{page_num}-{i}",
                        **metadata,
                    },
                )
                doc_chunks.append(doc)

        return doc_chunks

    def get_docChunks(self):

        raw_pages, metadata = self.parse_pdf()

        cleaning_functions = [
            self.merge_hyphenated_words,
            self.fix_newlines,
            self.remove_multiple_newlines,
        ]
        cleaned_text_pdf = self.clean_text(raw_pages, cleaning_functions)
        document_chunks = self.text_to_docs(cleaned_text_pdf, metadata)

        # Optional: Reduce embedding cost by only using the first 23 pages
        # document_chunks = document_chunks[:70]

        return document_chunks

    def get_vectorDB(self, return_docs=False):

        document_chunks = self.get_docChunks()
        self.vector_store = FAISS.from_documents(
            document_chunks,
            self.embeddings
        )
        if return_docs:
            return self.vector_store, document_chunks

        return self.vector_store

from abc import ABC, abstractmethod
import requests
import justext

import streamlit as st

from langchain.chains import RetrievalQA
from langchain.chains.summarize import load_summarize_chain
from Serp.serp import CustomSerpAPIWrapper
from langchain.agents import load_tools


class CustomTool(ABC):
    @abstractmethod
    def run(self, query: str):
        pass


class SummarizationTool(CustomTool):
    def __init__(self, llm, document_chunks):
        self.chain = load_summarize_chain(llm, chain_type="map_reduce")
        self.document_chunks = document_chunks

    def run(self, query: str):
        return self.run_chain()

    @st.cache
    def run_chain(self):
        return self.chain.run(self.document_chunks)


class LookupTool(CustomTool):
    def __init__(self, llm, vector_store):
        self.retrieval = RetrievalQA.from_chain_type(
            llm=llm, chain_type="stuff", retriever=vector_store.as_retriever(),
            return_source_documents=True
        )

    def run(self, query: str):
        res = self.retrieval(query)
        st.session_state.doc_sources = res['source_documents']
        return res['result']


class ArxivTool(CustomTool):
    def __init__(self, llm):
        self.arxiv = load_tools(["arxiv"], llm=llm)[0]

    def run(self, query: str):
        response = self.arxiv.run(query)
        st.session_state.google_sources.append(response)
        return response


class WebSearchTool(CustomTool):
    def __init__(self):
        self.search = CustomSerpAPIWrapper(serpapi_api_key=st.secrets['serp_api_key'])
        self.answer = ""
        self.source_dict = {}
        self.title = ""
        self.link = ""
        self.snippet = ""
        self.idx = 0

    def get_title(self):
        if "title" in self.source_dict['organic_results'][self.idx]:
            return self.source_dict['organic_results'][self.idx]['title']

    def get_link(self):
        if "link" in self.source_dict['organic_results'][self.idx]:
            return self.source_dict['organic_results'][self.idx]['link']

    def get_snippet(self):
        if "snippet" in self.source_dict['organic_results'][self.idx]:
            return self.source_dict['organic_results'][self.idx]['snippet']

    def get_paragraphs(self, paragraphs):

        relevant_paragraphs = []
        for paragraph in paragraphs:
            if paragraph.class_type == "good":
                relevant_paragraphs.append(paragraph)

        answer = ""

        # Define the number of paragraphs to consider from each section
        num_paragraphs_beginning = int(len(relevant_paragraphs) * 0.40)
        num_paragraphs_middle = int(len(relevant_paragraphs) * 0.50)
        num_paragraphs_end = int(len(relevant_paragraphs) * 0.10)

        # Extract paragraphs from the beginning
        words_count = 0
        for i in range(min(num_paragraphs_beginning, len(relevant_paragraphs))):
            paragraph = relevant_paragraphs[i]
            if paragraph.words_count > 40:
                if words_count < 50:
                    # print(f"Got from beg : {paragraph.text}\n\n")
                    answer += paragraph.text + "\n"
                    words_count += paragraph.words_count

        # Extract paragraphs from the middle
        words_count = 0
        middle_start = len(relevant_paragraphs) // 2 - num_paragraphs_middle // 2
        middle_end = middle_start + num_paragraphs_middle

        for i in range(middle_start, middle_end):
            if 0 <= i < len(relevant_paragraphs):
                paragraph = relevant_paragraphs[i]
                if paragraph.words_count > 10:
                    if words_count < 50:
                        # print(f"Got from mid : {paragraph.text}\n\n")
                        answer += paragraph.text + "\n"
                        words_count += paragraph.words_count

        # Extract paragraphs from the end
        words_count = 0
        end_start = len(relevant_paragraphs) - num_paragraphs_end
        end_end = len(relevant_paragraphs)

        for i in range(end_start, end_end):
            if 0 <= i < len(relevant_paragraphs):
                paragraph = relevant_paragraphs[i]
                if paragraph.words_count > 20:
                    if words_count < 50:
                        # print(f"Got from end : {paragraph.text}\n\n")
                        answer += paragraph.text + "\n"
                        words_count += paragraph.words_count

        return answer

    def get_answer(self):

        answer = "No Text Scraped"
        try:
            response = requests.get(self.link)
            paragraphs = justext.justext(response.content, justext.get_stoplist("English"))

        except Exception as e:
            return answer

        answer = self.get_paragraphs(paragraphs)

        return answer

    def run(self, query: str):

        result = self.search.run(query)
        self.source_dict = result['source_dict']
        self.idx = result['idx']

        self.title = self.get_title()
        self.link = self.get_link()
        self.snippet = self.get_snippet()
        self.answer = self.get_answer()
        st.session_state.google_sources.append({"title": self.title, "link": self.link,
                                                "snippet": self.snippet, "answer": self.answer})

        return self.answer
